def tops(msg: str) -> str:
    if not msg:
        return ""

    # Create a dictionary to map each character to its position in the string
    char_positions = {c: i for i, c in enumerate(msg)}

    # Determine the maximum possible top level
    max_level = 0
    for i, c in enumerate(msg):
        level = 0
        while i - level >= 0 and i + level < len(msg) and msg[i - level] == msg[i + level]:
            level += 1
        max_level = max(max_level, level)

    # For each character, determine its top level
    top_levels = {}
    for i, c in enumerate(msg):
        level = 0
        while i - level >= 0 and i + level < len(msg) and msg[i - level] == msg[i + level]:
            level += 1
        top_levels[c] = level

    # Collect all characters with their top levels
    chars_with_levels = [(c, top_levels[c]) for c in msg]
    # Remove duplicates by keeping the first occurrence of each character
    unique_chars = {}
    for c, level in chars_with_levels:
        if c not in unique_chars:
            unique_chars[c] = level

    # Sort characters by their top levels in descending order
    sorted_chars = sorted(unique_chars.items(), key=lambda x: -x[1])

    # Extract the characters in the sorted order
    result = [c for c, level in sorted_chars]

    return ''.join(result)
